let currentUser=null,needsSetup=false,routeVersion=0;
async function legacyApi(url,method='GET',body){const r=await fetch('/api/'+url,{signal:AbortSignal.timeout(20000),method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error||'Não foi possível carregar.'),{code:data.code,status:r.status,outcomeUnknown:method!=='GET'&&r.status>=500});return data;}
async function api(url,method='GET',body){await integrationReady;if(integrationState.error)throw integrationState.error;if(usesFatek())return integrationState.client.request(url,method,body,legacyApi,/^\/msadm\/?$/.test(location.pathname));return legacyApi(url,method,body);}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const formatPhone=v=>{const d=String(v||'').replace(/\D/g,'').slice(0,11);if(d.length>6)return `(${d.slice(0,2)}) ${d.slice(2,d.length>10?7:6)}-${d.slice(d.length>10?7:6)}`;if(d.length>2)return `(${d.slice(0,2)}) ${d.slice(2)}`;return d;};
const dateLabel=d=>new Date(d).toLocaleDateString('pt-BR');
function authView(admin=false,register=false){if(admin)return `<section class="admin-auth admin-login"><form data-account-form="login" data-admin="true" aria-label="Acesso administrativo">${field('Login','email','','email','required maxlength="160" autocomplete="username"')}${field('Senha','password','','password','required maxlength="128" autocomplete="current-password"')}<p class="form-error" role="alert"></p><button class="btn dark" type="submit">Entrar</button></form></section>`;const setup=admin&&needsSetup;return `<section class="auth-layout ${admin?'admin-auth':''}"><div class="auth-intro"><div class="eyebrow">${admin?'GESTÃO MS ATACADO':'ÁREA DE LOJISTAS'}</div><h1>${admin?'Gestão da loja':'Acesse sua<br>conta na MS.'}</h1><p>${admin?'Organize o catálogo, acompanhe pedidos e clientes.':'Salve seus pedidos e acompanhe seu histórico na loja.'}</p><img src="/assets/hero.webp" alt="Peças de jeans dobradas"></div><div class="auth-panel"><div class="eyebrow">${setup?'PRIMEIRO ACESSO':register?'CADASTRO':'ACESSO'}</div><h2>${setup?'Criar administrador':register?'Criar conta':admin?'Entrar no painel':'Entrar'}</h2><form data-account-form="${setup?'setup':register?'register':'login'}" data-admin="${admin}">${setup||register?field('Nome','name','','text','required minlength="2" maxlength="100" autocomplete="name"'):''}${register?field('WhatsApp','phone','','tel','maxlength="15" inputmode="numeric" autocomplete="tel" placeholder="(51) 99999-9999" data-phone-input'):''}${field('E-mail','email','','email','required maxlength="160" autocomplete="username"')}${field('Senha','password','','password',`required minlength="10" maxlength="128" autocomplete="${register||setup?'new-password':'current-password'}"`)}<small>Mínimo de 10 caracteres.</small><p class="form-error" role="alert"></p><button class="btn dark" type="submit">${setup?'Criar acesso':register?'Criar minha conta':'Entrar'}</button></form>${admin?'':`<p class="auth-switch">${register?'Já tem conta? <a href="#conta">Entrar</a>':'Ainda não tem conta? <a href="#cadastro">Cadastre-se</a>'}</p>`}<a class="text-link" href="#catalogo">Voltar ao catálogo</a></div></section>`;}
function shell(title,subtitle,content,admin=false){const links=admin?[['admin','Visão geral'],['admin/home','Capa da loja'],['admin/pedidos','Pedidos'],['admin/produtos','Catálogo'],['admin/categorias','Categorias'],['admin/frete','Frete'],['admin/clientes','Clientes']]:[['conta','Meus pedidos'],['conta/dados','Meus dados']];return `<div class="workspace"><aside class="account-sidebar">${admin?'<button class="admin-menu-toggle" type="button" aria-expanded="false" aria-controls="admin-navigation"><span aria-hidden="true">☰</span> Menu do painel</button>':''}<div class="eyebrow">${admin?'ADMINISTRAÇÃO':'MINHA CONTA'}</div><strong>${esc(currentUser.name)}</strong><small>${esc(currentUser.email)}</small><nav ${admin?'id="admin-navigation"':''} aria-label="Menu da conta">${links.map(([href,label])=>`<a class="${(location.hash||'#admin')==='#'+href?'selected':''}" href="#${href}">${label}</a>`).join('')}</nav><div class="sidebar-footer"><a href="#catalogo">Ver catálogo</a><button class="logout" data-logout>Sair</button></div></aside><section class="account-content"><div class="account-head"><div><div class="eyebrow">MS ATACADO · ${admin?'GESTÃO':'CLIENTE'}</div><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div></div>${content}</section></div>`;}
const hrefOptions=[['#catalogo','Catálogo completo'],['#catalogo?tipo=Calças','Catálogo · Calças'],['#catalogo?tipo=Shorts','Catálogo · Shorts'],['#como-comprar','Como comprar'],['#atendimento','Atendimento / WhatsApp'],['#loja','Loja física']];
function homeAdmin(){return `<div class="home-editor"><section class="hero home-preview" aria-label="Prévia da capa"><div class="hero-copy"><div class="eyebrow" data-preview="eyebrow">${esc(hero.eyebrow)}</div><h1><span data-preview="headline">${esc(hero.headline)}</span><br><span data-preview="highlight">${esc(hero.highlight)}</span></h1><p data-preview="subtitle">${esc(hero.subtitle)}</p><a class="btn" data-preview="cta" href="${esc(hero.ctaHref)}">${esc(hero.ctaText)}</a></div><div class="hero-photo"><img data-preview="image" src="${esc(hero.image)}" alt="${esc(hero.headline)}"><div class="hero-label"><strong>06</strong><div>PEÇAS NO MÍNIMO<small>Modelos e tamanhos variados</small></div></div></div></section><form data-home-form class="order-card"><div class="product-fields-row">${field('Selo superior','eyebrow',hero.eyebrow,'text','required minlength="2" maxlength="60"')}${field('Título principal','headline',hero.headline,'text','required minlength="2" maxlength="80"')}${field('Destaque em âmbar','highlight',hero.highlight,'text','required minlength="2" maxlength="60"')}</div><label class="field">Subtítulo<textarea name="subtitle" required minlength="5" maxlength="220">${esc(hero.subtitle)}</textarea></label><div class="product-fields-row">${field('Texto do botão','ctaText',hero.ctaText,'text','required minlength="2" maxlength="36"')}<label class="field">Destino do botão<select name="ctaHref">${hrefOptions.map(([v,l])=>`<option value="${esc(v)}" ${hero.ctaHref===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="field">Foto da capa<label class="photo-upload">Trocar imagem<input type="file" data-home-photo accept="image/jpeg,image/png,image/webp"></label><small class="muted" data-home-photo-status>JPG, PNG ou WebP · até 8 MB</small></div></div><p class="form-error" role="alert"></p><div class="product-form-actions"><button type="button" class="btn outline" data-reset-home>Restaurar padrão da MS</button><button type="submit" class="btn dark">Salvar e publicar na home</button></div></form></div>`;}
function orderCards(orders,admin=false){return orders.length?orders.map(o=>`<article class="order-card"><div class="order-heading"><div><strong>Pedido #${o.id.slice(0,8).toUpperCase()}</strong><small>${dateLabel(o.created)} · ${o.items.reduce((s,i)=>s+i.qty,0)} peças</small>${orderShippingBadge(o)}${admin?`<p>${esc(o.name)} · ${esc(o.email)}${o.phone?' · '+esc(formatPhone(o.phone)):''}</p>`:''}</div><span class="status-pill">${esc(o.status)}</span></div><details><summary>Peças do pedido (${o.items.reduce((s,i)=>s+i.qty,0)})</summary>${o.items.map(i=>`<div class="order-item"><img src="${productImage(i.image)}" alt=""><div><strong>${esc(i.name)}</strong><p>Tamanho ${esc(i.size)}</p></div><span>${i.qty} un.</span></div>`).join('')}</details>${admin?`<form data-status="${o.id}" class="status-form"><label>Situação <select name="status">${['Salvo','Em análise','Concluído','Cancelado'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn outline">Atualizar</button><span class="form-error" role="alert"></span></form>`:''}</article>`).join(''):'<div class="account-empty"><span class="empty-number">06</span><h2>Nenhum pedido salvo</h2><p>Monte seu pedido no catálogo a partir de 6 peças.</p><a class="btn" href="#catalogo">Ver catálogo</a></div>';}
function keepPrerenderedImages(old){if(!old.length)return;main.querySelectorAll('img').forEach(img=>{const i=old.findIndex(o=>o.getAttribute('src')===img.getAttribute('src')&&(o.getAttribute('srcset')||'')===(img.getAttribute('srcset')||''));if(i<0)return;const o=old.splice(i,1)[0];[...img.attributes].forEach(at=>o.setAttribute(at.name,at.value));img.replaceWith(o);});}
const originalRoute=route;
route=async function(){renderedLocation=location.href;const version=++routeVersion;await integrationReady;if(integrationState.error){main.innerHTML='<section class="info-page"><h1>Conexão indisponível</h1><p>Não foi possível carregar a loja. Recarregue para tentar novamente.</p></section>';return;}const adminPath=/^\/msadm\/?$/.test(location.pathname);const page=location.hash.slice(1)||(adminPath?'admin':publicRoute());if(page.startsWith('admin')&&!adminPath){location.replace('/msadm'+(page==='admin'?'':'#'+page));return;}if(adminPath&&!page.startsWith('admin')){location.assign('/#'+page);return;}if(!/^(conta|cadastro|admin)(\/|$)/.test(page)){if(usesFatek()||!main.querySelector('[data-prerender]'))main.innerHTML='<section class="store-loading wrap" aria-busy="true"><p role="status">Carregando a loja…</p><div class="loading-placeholder"></div><div class="loading-placeholder short"></div></section>';window.scrollTo(0,0);try{await loadProducts();if(version===routeVersion){const images=[...main.querySelectorAll('[data-prerender] img')];originalRoute();if(!usesFatek())keepPrerenderedImages(images);}}catch(e){if(version===routeVersion)main.innerHTML='<section class="store-loading wrap"><h1>Não foi possível carregar a loja.</h1><p>Confira sua conexão e tente novamente.</p><button class="btn" data-retry>Tentar novamente</button></section>';}return;}main.innerHTML='<section class="info-page"><p role="status">Carregando sua área…</p></section>';window.scrollTo(0,0);try{const session=await api('session');if(version!==routeVersion)return;currentUser=session.user;needsSetup=session.setupNeeded;const admin=page.startsWith('admin');document.title='MS Atacado — '+(admin?'Painel administrativo':'Minha conta');if(usesFatek()&&!admin&&['conta/recuperar','conta/nova-senha'].includes(page)){main.innerHTML=fatekRecovery(page==='conta/nova-senha');return;}if(!currentUser||(admin&&!session.adminAuthenticated)){main.innerHTML=authView(admin,page==='cadastro');if(usesFatek()&&!admin)main.insertAdjacentHTML('beforeend','<p class="wrap"><a href="#conta/recuperar">Esqueci minha senha</a></p>');return;}if(admin&&currentUser.role!=='admin'){main.innerHTML=shell('Acesso restrito','Esta conta não tem acesso ao painel.','<a class="btn" href="#conta">Ir para minha conta</a>');return;}
 if(admin){await loadProducts();const data=await api('admin/overview');if(version!==routeVersion)return;let content,title,subtitle='';
 if(page==='admin/home'){title='Capa da loja';subtitle='Personalize o banner principal para campanhas, novidades ou datas especiais.';content=homeAdmin();}
 else if(page==='admin/produtos'){title='Seu catálogo.';subtitle=usesFatek()?'Cadastre e edite os produtos compartilhados com o ERP.':'Organize suas peças, fotos e estoque.';content=catalogAdmin();}
 else if(page==='admin/categorias'){title='Categorias';subtitle='Crie categorias para organizar as peças da loja.';content=categoryAdmin();}
 else if(page==='admin/frete'){title='Frete e entrega';if(usesFatek()){subtitle='Cotações e regras de entrega são gerenciadas no ERP.';content='<div class="order-card"><h2>Entrega conectada ao ERP</h2><p>O carrinho consulta as opções atuais de entrega. Configure origem, transportadoras e medidas no ERP com seu acesso autorizado.</p><a class="btn outline" href="https://crm.fatek.solutions/settings/shipping" target="_blank" rel="noopener">Abrir entrega no ERP</a></div>';}else{adminShippingConfig=await api('admin/shipping');if(version!==routeVersion)return;subtitle='Configure o Melhor Envio, o CEP de origem e o peso médio das peças.';content=shippingAdmin();}}
 else if(page==='admin/clientes'){title='Clientes';content=data.customers.length?`<div class="customer-list">${data.customers.map(c=>`<article class="order-card"><strong>${esc(c.name)}</strong><p>${esc(c.email)}${c.phone?' · '+esc(formatPhone(c.phone)):''}</p><small>Desde ${dateLabel(c.created)} · ${data.orders.filter(o=>o.user_id===c.id).length} pedidos</small></article>`).join('')}</div>`:'<div class="account-empty"><h2>Nenhum cliente cadastrado</h2></div>';}
 else if(page==='admin/pedidos'){title='Pedidos';content=orderCards(data.orders,true);}
 else{title='Visão geral';content=`<div class="stats"><article><span>Pedidos</span><strong>${data.orders.length}</strong></article><article><span>Clientes</span><strong>${data.customers.length}</strong></article><article><span>Modelos</span><strong>${products.length}</strong></article></div><div class="dashboard-banner"><div><h2>Personalizar loja e catálogo</h2><p>Edite a capa da home para promoções ou atualize fotos e grade das peças.</p></div><div class="dashboard-actions"><a class="btn outline" href="#admin/home">Capa da loja</a><a class="btn" href="#admin/produtos">Editar catálogo</a></div></div><h2>Pedidos recentes</h2>${orderCards(data.orders.slice(0,3),true)}`;}
 main.innerHTML=shell(title,subtitle,content,true);if(usesFatek())main.insertAdjacentHTML('afterbegin','<aside class="hint">'+(page==='admin/produtos'?'Cadastre aqui ou no ERP: os produtos são os mesmos. Entradas e ajustes de estoque são feitos no ERP.':page==='admin/frete'?'O frete do catálogo conectado segue as configurações atuais do ERP.':'Pedidos e clientes exibidos aqui são o histórico anterior deste painel. Novos pedidos e cadastros comerciais ficam no ERP.')+'</aside>');if(page==='admin/produtos')renderAdminList();
 }else if(page==='conta/dados'){let revision='';if(usesFatek()){const result=await integrationState.client.profile();if(!result.profile){main.innerHTML=shell('Meus dados','Cadastro aguardando conferência da equipe.','');return;}currentUser.name=result.profile.name;currentUser.phone=result.profile.phone||currentUser.phone;revision=result.profile.revision;}main.innerHTML=shell('Meus dados','',`<form data-account-form="profile" data-revision="${esc(revision)}" class="profile-form">${field('Nome','name',currentUser.name,'text','required minlength="2" maxlength="100"')}${field('E-mail','email',currentUser.email,'email','disabled')}${field('WhatsApp','phone',formatPhone(currentUser.phone||''),'tel','maxlength="15" inputmode="numeric" autocomplete="tel" data-phone-input')}<p class="form-error" role="alert"></p><button class="btn dark">Salvar dados</button></form>`);}
 else{const orders=await api('orders');if(version!==routeVersion)return;main.innerHTML=shell('Meus pedidos','',orderCards(orders));}
 }catch(e){if(version===routeVersion)main.innerHTML=`<section class="info-page"><h1>Não foi possível carregar.</h1><p>${esc(e.message)}</p><button class="btn" data-retry>Tentar novamente</button></section>`;}};
document.addEventListener('input',e=>{if(e.target.matches('[data-phone-input]'))e.target.value=formatPhone(e.target.value);const form=e.target.closest('[data-home-form]');if(!form)return;const v=Object.fromEntries(new FormData(form));for(const k of ['eyebrow','headline','highlight','subtitle']){const el=document.querySelector(`[data-preview="${k}"]`);if(el&&v[k]!==undefined)el.textContent=v[k];}const cta=document.querySelector('[data-preview="cta"]');if(cta){cta.textContent=v.ctaText||'';cta.setAttribute('href',v.ctaHref||'#catalogo');}});
document.addEventListener('change',async e=>{const input=e.target;if(!input.matches('[data-home-photo]'))return;const file=input.files?.[0];if(!file)return;const status=document.querySelector('[data-home-photo-status]'),error=input.closest('form')?.querySelector('.form-error');if(error)error.textContent='';if(file.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){if(error)error.textContent='Use JPG, PNG ou WebP de até 8 MB.';input.value='';return;}input.disabled=true;if(status)status.textContent='Enviando imagem…';try{const base64=await prepareUpload(file);hero={...defaultHero,...await api('admin/home/photo','POST',{base64})};const img=document.querySelector('[data-preview="image"]');if(img)img.src=hero.image;if(status)status.textContent='Imagem atualizada na home.';toast('Foto da capa atualizada.');}catch(err){if(error)error.textContent=err.message;if(status)status.textContent='JPG, PNG ou WebP · até 8 MB';}finally{input.disabled=false;input.value='';}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-account-form],[data-product],[data-status],[data-home-form]'))return;e.preventDefault();const button=form.querySelector('button:not([type="button"])');button.disabled=true;const error=form.querySelector('.form-error');error.textContent='';try{const values=Object.fromEntries(new FormData(form));if(form.hasAttribute('data-home-form')){hero={...defaultHero,...await api('admin/home','PATCH',values)};toast('Capa publicada na home.');}else if(form.dataset.accountForm){const action=form.dataset.accountForm;const endpoint=action==='login'&&form.dataset.admin==='true'?'admin/login':action;if(action==='profile'&&usesFatek())values.revision=form.dataset.revision;const result=await api(endpoint,action==='profile'?'PATCH':'POST',values);if(result.confirmationRequired){error.textContent='Confira seu e-mail para confirmar o cadastro e depois entrar.';return;}if(result.message){error.textContent=result.message;return;}if(action!=='profile'){const confirmed=await api('session');if(!confirmed.user)throw new Error('O navegador não manteve seu login. Permita cookies para este endereço e tente novamente.');}currentUser=result.user;if(action==='profile'){toast('Dados atualizados.');}else{location.hash=form.dataset.admin==='true'?'admin':'conta';await route();if(sessionStorage.getItem('ms-save-after-login')){sessionStorage.removeItem('ms-save-after-login');renderCart();dialog.showModal();}}}else if(form.dataset.product){values.variants=[...form.querySelectorAll('.stock-row')].map(row=>({size:row.querySelector('[data-stock-size]').value,quantity:Number(row.querySelector('[data-stock-quantity]').value)}));values.inventoryVersion=Number(form.querySelector('[data-version]').dataset.version);await api('admin/admin/products'.replace('admin/admin','admin')+'/'+form.dataset.product,'PATCH',values);await loadProducts();form.querySelector('[data-version]').dataset.version=products.find(p=>p.id===form.dataset.product).inventoryVersion;toast('Catálogo atualizado.');}else{await api('admin/orders/'+form.dataset.status,'PATCH',values);await route();toast('Situação atualizada.');}}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-retry'))route();if(el.hasAttribute('data-reset-home')){el.disabled=true;try{hero={...defaultHero,...await api('admin/home','DELETE',{})};await route();toast('Capa padrão restaurada.');}catch(err){toast(err.message);}finally{el.disabled=false;}}if(el.hasAttribute('data-logout')){try{await api('logout','POST',{});currentUser=null;await route();}catch(err){toast(err.message);}}},false);
// Intercept review before the existing demo-only cart handler.
document.addEventListener('click',async e=>{const button=e.target.closest('[data-review],[data-save-order]');if(!button||usesFatek())return;e.stopImmediatePropagation();if(cart.reduce((s,i)=>s+i.qty,0)<6)return;button.disabled=true;try{const session=await api('session');currentUser=session.user;if(!currentUser){sessionStorage.setItem('ms-save-after-login','1');dialog.close();location.hash='conta';await route();return;}if(button.hasAttribute('data-review')){document.querySelector('#cart-body').innerHTML=`<div class="success"><h3>Confirmar pedido?</h3><p>${cart.reduce((s,i)=>s+i.qty,0)} peças selecionadas para ${esc(currentUser.name)}.</p>${selectedShipping?`<p class="order-shipping">Entrega: <strong>${esc(selectedShipping.name)}</strong> · ${esc(formatBrl(selectedShipping.price))}</p>`:''}</div><button class="btn dark" data-save-order>Salvar pedido na minha conta</button><button class="btn outline" data-back-cart>Voltar às peças</button>`;}else{await api('orders','POST',{items:cart,shipping:selectedShipping});cart=[];selectedShipping=null;cartShippingQuotes=null;save();await loadProducts();dialog.close();location.hash='conta';await route();toast('Pedido salvo na sua conta.');}}catch(err){if(/frete/i.test(err.message||'')){selectedShipping=null;cartShippingQuotes=null;cartShippingSignature='';}toast(err.message);}finally{button.disabled=false;}},true);
async function loadProducts(){await integrationReady;if(integrationState.error)throw integrationState.error;if(usesFatek()){integrationState.info=await integrationState.client.api.store();initializeFatekCart();}const [list,banner,categoryList]=await Promise.all([api('products'),api('home').catch(()=>defaultHero),api('categories')]);categories=categoryList;products.splice(0,products.length,...list);hero={...defaultHero,...banner};}
route();
